-- ---------- Pengaturan baru ----------
UPDATE pengaturan SET nilai = 'Assalamu''alaikum warahmatullahi wabarakatuh, salam sejahtera untuk kita semua.\n\nSelamat datang di website resmi Desa Marga Mulya. Desa kami terbentang dari pesisir Laut Jawa sampai hamparan sawah di selatan. Di sini nelayan, petani, pengolah ikan, dan pengrajin batok kelapa hidup berdampingan dan saling menguatkan.\n\nWebsite ini kami hadirkan supaya pelayanan desa terasa lebih dekat. Warga bisa mengajukan surat dari rumah, memantau bantuan sosial, menyampaikan aspirasi, dan ikut mengawasi anggaran serta pembangunan desa secara terbuka. Bagi bapak dan ibu yang belum terbiasa memakai internet, pintu kantor desa tetap terbuka dan petugas siap membantu.\n\nKepada para tamu, selamat datang di Marga Mulya. Nikmati pantai, mangrove, dan sawah kami, cicipi olahan ikan dan kelapa buatan warga, dan bantu kami menjaga alam tetap bersih. Mari bersama membangun Marga Mulya yang guyub, sejahtera, dan tangguh.\n\nWassalamu''alaikum warahmatullahi wabarakatuh.' WHERE kunci = 'sambutan_kades' AND nilai = '';
UPDATE pengaturan SET nilai = '/assets/img/kades.svg' WHERE kunci = 'foto_kades' AND nilai = '';
UPDATE pengaturan SET nilai = 'Data asli: luas wilayah, jumlah RW dan RT, serta penduduk menurut jenis kelamin dari BPS (Kecamatan Mauk Dalam Angka 2025, data 2024). Angka bertanda (ilustrasi) adalah contoh yang disusun mengikuti format Data EcoQuest A sampai M, dan akan diganti dengan data resmi dari kantor desa.' WHERE kunci = 'catatan_data' AND nilai LIKE 'Data asli: luas wilayah, jarak%';

