-- ---------- Budaya dan kesenian: isi kolom baru untuk 3 kegiatan lama (hanya yang masih kosong) ----------
UPDATE budaya SET jenis = 'Tradisi pesisir', foto = '/assets/img/budaya-sedekah-laut.svg', ilustrasi = 1, urutan = 10 WHERE id = 1 AND foto IS NULL;
UPDATE budaya SET jenis = 'Gotong royong', foto = '/assets/img/budaya-bersih-pantai.svg', ilustrasi = 1, urutan = 60 WHERE id = 2 AND foto IS NULL;
UPDATE budaya SET jenis = 'Gotong royong', foto = '/assets/img/mangrove.svg', ilustrasi = 1, urutan = 70 WHERE id = 3 AND foto IS NULL;
UPDATE budaya SET isi = 'Warga, pemuda, dan pengunjung memungut sampah plastik di pesisir dan saluran, lalu memilahnya untuk dijual ke pengepul. Hasilnya masuk kas Karang Taruna.' WHERE id = 2 AND isi LIKE '%bank sampah%';

-- ---------- Wisata: waktu terbaik (hanya kalau masih kosong) ----------
UPDATE wisata SET waktu_terbaik = 'Pagi 06.00 sampai 09.00 untuk matahari terbit, atau sore menjelang senja. Hindari saat air pasang tinggi dan angin barat.' WHERE slug = 'pantai-pasir-putih' AND waktu_terbaik = '';
UPDATE wisata SET waktu_terbaik = 'Pagi hari saat air surut, supaya akar bakau dan kepiting terlihat. Musim hujan cocok untuk ikut tanam bibit.' WHERE slug = 'mangrove' AND waktu_terbaik = '';
UPDATE wisata SET waktu_terbaik = 'Pukul 07.00 sampai 10.00, saat perahu pulang melaut dan ikan dilelang di tepi dermaga.' WHERE slug = 'kampung-nelayan' AND waktu_terbaik = '';
UPDATE wisata SET waktu_terbaik = 'Hari kerja pukul 09.00 sampai 14.00, saat pengrajin bekerja. Bisa dikunjungi saat hujan.' WHERE slug = 'batok-kelapa' AND waktu_terbaik = '';

-- ---------- Layanan surat baru (hanya ditambah kalau belum ada) ----------
