-- ---------- Program bantuan: penjelasan lengkap (kolom baru, hanya yang masih kosong) ----------
UPDATE bantuan SET kategori = 'Sosial', ilustrasi = 1, manfaat = 'Uang tunai Rp300.000 per keluarga per bulan (ilustrasi, mengikuti aturan BLT Dana Desa yang berlaku)', deskripsi = 'Bantuan tunai dari Dana Desa untuk keluarga miskin yang belum menerima bantuan sosial lain seperti PKH atau BPNT. Penerima ditetapkan lewat musyawarah desa khusus dan diumumkan di papan kantor desa.' WHERE id = 1 AND deskripsi IS NULL;
UPDATE bantuan SET kategori = 'Nelayan', ilustrasi = 1, manfaat = 'Pelampung, jaket keselamatan, dan lampu navigasi untuk perahu kecil (ilustrasi)', deskripsi = 'Paket alat keselamatan untuk nelayan kecil supaya lebih aman melaut, terutama saat musim angin barat. Penerima wajib terdaftar di kelompok nelayan dan memiliki Kartu KUSUKA.' WHERE id = 2 AND deskripsi IS NULL;
UPDATE bantuan SET kategori = 'Usaha', ilustrasi = 1, manfaat = 'Pelatihan 3 hari dan pinjaman modal bergulir tanpa bunga (ilustrasi)', deskripsi = 'Pelatihan membuat kerajinan batok kelapa, briket arang, dan olahan ikan, dilanjutkan pinjaman modal bergulir dari BUMDes untuk peserta yang siap memulai usaha.' WHERE id = 3 AND deskripsi IS NULL;
Memiliki minimal satu komponen: ibu hamil, balita, anak sekolah, lansia 60 tahun ke atas, atau disabilitas berat
Bersedia mengikuti pertemuan kelompok bulanan dengan pendamping PKH', 'Bertahap setiap triwulan sesuai jadwal Kementerian Sosial', 'Usulkan diri lewat musyawarah desa atau ketua RT supaya masuk DTKS. Cek kepesertaan di cekbansos.kemensos.go.id.', 'Bantuan tunai bertahap; besarnya mengikuti komponen anggota keluarga', 'https://cekbansos.kemensos.go.id', 'Bantuan tunai bersyarat untuk keluarga miskin. Syaratnya, anak tetap sekolah, balita rutin ke posyandu, dan ibu hamil memeriksakan kandungan. Pendamping PKH di kecamatan membantu keluarga penerima.', '4', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Program Keluarga Harapan (PKH)');
Belum menerima bantuan pangan serupa
Memiliki Kartu Keluarga yang aktif', 'Penyaluran berkala sesuai jadwal Kementerian Sosial', 'Usulkan lewat ketua RT atau musyawarah desa. Cek kepesertaan di cekbansos.kemensos.go.id.', 'Bantuan untuk membeli bahan pangan pokok seperti beras, telur, dan lauk', 'https://cekbansos.kemensos.go.id', 'Bantuan pangan untuk membantu keluarga memenuhi kebutuhan gizi sehari-hari. Penerima dan jadwalnya ditentukan pemerintah pusat berdasarkan DTKS.', '4', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Bantuan Pangan Non Tunai (Program Sembako)');
Diutamakan pemegang Kartu Indonesia Pintar atau dari keluarga penerima PKH
Diusulkan oleh sekolah', 'Setiap tahun ajaran', 'Hubungi wali kelas atau operator sekolah supaya diusulkan. Desa bisa membantu surat keterangan tidak mampu (SKTM).', 'Uang bantuan biaya sekolah per tahun sesuai jenjang', '', 'Bantuan tunai supaya anak dari keluarga kurang mampu tetap sekolah sampai lulus. Desa membantu lewat surat keterangan tidak mampu.', '4', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Program Indonesia Pintar (PIP)');
Memiliki NIK yang aktif di Disdukcapil', 'Sepanjang tahun', 'Ajukan lewat desa dengan membawa Kartu Keluarga, lalu desa meneruskan usulan ke Dinas Sosial Kabupaten Tangerang.', 'Iuran BPJS Kesehatan dibayar pemerintah, berobat gratis di fasilitas kesehatan', '', 'Iuran BPJS Kesehatan warga tidak mampu ditanggung pemerintah, sehingga bisa berobat di puskesmas dan rumah sakit rujukan tanpa biaya.', '1', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Jaminan kesehatan PBI (KIS)');
Memiliki KTP dan Kartu Keluarga
Terdaftar di kelompok nelayan desa (dianjurkan)', 'Pendataan dibuka sepanjang tahun', 'Daftar lewat penyuluh perikanan kecamatan atau ketua kelompok nelayan. Desa membantu surat keterangan usaha.', 'Kartu identitas pelaku usaha perikanan, syarat untuk menerima bantuan dan asuransi nelayan', '', 'Kartu KUSUKA menjadi tanda resmi bahwa seseorang adalah pelaku usaha perikanan. Tanpa kartu ini, nelayan sulit menerima bantuan alat tangkap, mesin perahu, dan asuransi.', '8', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Kartu KUSUKA untuk nelayan');
Berusia maksimal 65 tahun
Belum terdaftar di asuransi serupa', 'Mengikuti kuota tahunan dinas perikanan', 'Daftar lewat penyuluh perikanan atau ketua kelompok nelayan.', 'Santunan bila terjadi kecelakaan saat melaut (ilustrasi)', '', 'Perlindungan untuk nelayan dan keluarganya bila terjadi kecelakaan kerja di laut. Preminya dibantu pemerintah untuk tahun pertama (ilustrasi).', '8', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Asuransi nelayan');
Terdaftar di rencana kebutuhan kelompok (RDKK)
Menggarap lahan paling luas 2 hektare', 'Menjelang setiap musim tanam', 'Daftar ke ketua Kelompok Tani Jamblang supaya masuk RDKK, lalu tebus pupuk di kios resmi dengan KTP.', 'Harga pupuk urea dan NPK lebih murah dari harga pasar', '', 'Pupuk dengan harga yang disubsidi pemerintah supaya biaya tanam petani lebih ringan. Kebutuhan tiap petani dicatat kelompok tani setiap musim.', '2', 0, 1, 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bantuan WHERE nama = 'Pupuk bersubsidi untuk petani');

