INSERT IGNORE INTO pengaturan (kunci, nilai) VALUES
('sambutan_nama', 'Kepala Desa Marga Mulya'),
('sambutan_ilustrasi', '1'),
('foto_kades_sumber', 'Gambar ilustrasi buatan tim website, bukan foto kepala desa'),
('foto_hero_sumber', ''),
('foto_hero_url', ''),
('catatan_logo', 'Logo website ini dibuat tim dengan bantuan AI dan bukan logo resmi Pemerintah Desa Marga Mulya.'),
('waktu_kunjung', 'Waktu paling nyaman berkunjung adalah pagi (06.00 sampai 10.00) dan sore (15.00 sampai 17.30), saat matahari tidak terlalu terik. Musim kemarau (Mei sampai September) paling cocok untuk ke pantai dan mangrove. Saat musim hujan dan angin barat (Desember sampai Februari), cek prakiraan gelombang dan jadwal air pasang sebelum berangkat.'),
('kode_etik_lengkap', 'Jaga alam|Jangan menginjak, mencabut, atau mematahkan bibit mangrove.\nJaga alam|Jangan mengambil kerang, karang, atau satwa dari pantai dan tambak warga.\nJaga alam|Bawa pulang sampahmu, terutama plastik dan puntung rokok.\nJaga alam|Bawa botol minum dan wadah makan sendiri supaya sampah berkurang.\nHormati warga|Minta izin sebelum memotret warga, rumah, atau perahu nelayan.\nHormati warga|Berpakaian sopan saat melewati kampung dan tempat ibadah.\nHormati warga|Pelankan suara dan musik, terutama saat azan dan malam hari.\nHormati warga|Parkir di tempat yang disediakan, jangan menutup jalan atau akses perahu.\nKeselamatan|Jangan berenang saat ombak tinggi, angin kencang, atau air pasang.\nKeselamatan|Awasi anak-anak di tepi pantai dan pematang tambak.\nKeselamatan|Ikuti arahan pemandu dan petugas desa di lokasi.\nKeselamatan|Simpan nomor darurat 112 dan nomor WhatsApp desa sebelum berangkat.\nDukung ekonomi warga|Belanja oleh-oleh dan makan di warung warga sekitar destinasi.\nDukung ekonomi warga|Bayar tiket dan parkir di loket resmi, minta bukti pembayarannya.\nRombongan, KKN, dan penelitian|Rombongan 10 orang atau lebih, KKN, dan penelitian mengajukan izin kunjungan lewat layanan surat paling lambat 7 hari sebelumnya.');
