INSERT IGNORE INTO lembaga (id, nama, jenis, kegiatan, jadwal, anggota, ilustrasi, urutan) VALUES
(1, 'Badan Permusyawaratan Desa (BPD)', 'Lembaga pemerintahan desa', 'Menampung aspirasi warga, membahas dan menyepakati peraturan desa serta APBDes', 'Musyawarah desa setiap triwulan', 7, 1, 10),
(2, 'Lembaga Pemberdayaan Masyarakat (LPM)', 'Lembaga kemasyarakatan', 'Merencanakan pembangunan bersama warga dan mengawasi pelaksanaannya', 'Rapat bulanan', 15, 1, 20),
(3, 'Tim Penggerak PKK', 'Lembaga kemasyarakatan', 'Posyandu, dasa wisma, kebun gizi pekarangan, dan pelatihan olahan pangan', 'Pertemuan setiap Kamis kedua', 40, 1, 30),
(4, 'Karang Taruna', 'Kepemudaan', 'Bersih pantai, tanam mangrove, turnamen olahraga, dan pelatihan usaha pemuda', 'Kumpul setiap Sabtu malam', 45, 1, 40),
(5, 'Kelompok nelayan (3 kelompok)', 'Kelompok usaha', 'Pendataan Kartu KUSUKA, simpan pinjam alat tangkap, dan penyuluhan keselamatan melaut', 'Pertemuan bulanan di dermaga', 96, 1, 50),
(6, 'Kelompok Tani Jamblang', 'Kelompok usaha', 'Mengatur jadwal tanam dan pengairan, penyaluran pupuk, dan percontohan benih padi', 'Pertemuan menjelang musim tanam', 60, 1, 60),
(7, 'Kampung KB Bebulak', 'Kesehatan dan keluarga', 'Penyuluhan keluarga berencana, pencegahan stunting, dan bina keluarga balita di RW 03', 'Setiap bulan bersama posyandu', 0, 0, 70),
(8, 'Posyandu (5 pos)', 'Kesehatan dan keluarga', 'Penimbangan balita, imunisasi, dan pemeriksaan ibu hamil serta lansia', 'Sebulan sekali di tiap RW', 25, 1, 80),
(9, 'Linmas (perlindungan masyarakat)', 'Keamanan', 'Ronda pos kamling, siaga banjir dan rob, serta pengamanan acara desa', 'Ronda bergilir setiap malam', 25, 1, 90),
(10, 'Majelis taklim', 'Keagamaan', 'Pengajian rutin ibu-ibu dan bapak-bapak, santunan anak yatim', 'Setiap Jumat sore dan Minggu pagi', 120, 1, 100),
(11, 'BUMDes Marga Mulya', 'Ekonomi desa', 'Unit simpan pinjam, pemasaran produk UMKM, dan pengelolaan wisata pantai', 'Laporan usaha setiap semester', 9, 1, 110),
(12, 'Kelompok Sadar Wisata (Pokdarwis)', 'Pariwisata', 'Menjadi pemandu, menjaga kebersihan destinasi, dan menyambut rombongan', 'Kerja bakti destinasi setiap Minggu', 20, 1, 120);
INSERT IGNORE INTO budaya (id, judul, jenis, waktu, isi, foto, ilustrasi, urutan) VALUES
(101, 'Gambang kromong (ilustrasi)', 'Kesenian musik', 'Saat hajatan dan perayaan kampung', 'Musik perpaduan budaya Betawi dan Tionghoa peranakan (Cina Benteng) yang tumbuh di pesisir Tangerang. Gambang, kromong, kendang, dan tehyan dimainkan bersama untuk mengiringi lagu dan tarian. Pengunjung rombongan bisa meminta pertunjukan singkat lewat izin kunjungan.', '/assets/img/budaya-gambang.svg', 1, 20),
(102, 'Marawis dan hadroh (ilustrasi)', 'Kesenian religi', 'Maulid, pernikahan, dan penyambutan tamu', 'Rebana dan marawis dimainkan remaja masjid sambil melantunkan selawat. Ada tiga kelompok yang berlatih bergiliran di musala. Penampilannya biasa membuka acara desa dan menyambut tamu rombongan.', '/assets/img/budaya-marawis.svg', 1, 30),
(103, 'Pencak silat dan palang pintu (ilustrasi)', 'Bela diri dan adat', 'Latihan setiap Sabtu malam', 'Pencak silat diajarkan turun-temurun di padepokan kampung. Dalam pernikahan, jagoan silat memeragakan palang pintu: berbalas pantun lalu adu jurus sebelum rombongan pengantin pria dipersilakan masuk.', '/assets/img/budaya-silat.svg', 1, 40),
(104, 'Panen bandeng bersama (ilustrasi)', 'Tradisi pesisir', 'Menjelang musim panen tambak', 'Pemilik tambak dan tetangga turun bersama menggiring bandeng ke sudut tambak. Sebagian hasil dimasak bersama, sebagian diolah ibu-ibu menjadi bandeng presto. Pengunjung boleh ikut dengan didampingi pemilik tambak.', '/assets/img/budaya-panen-tambak.svg', 1, 50),
(105, 'Muludan kampung (ilustrasi)', 'Tradisi keagamaan', 'Bulan Rabiulawal', 'Peringatan Maulid Nabi diisi pengajian, marawis, dan arak-arakan panjang mulud berisi telur dan makanan yang dibagikan ke warga. Seluruh RW bergiliran menjadi tuan rumah.', '/assets/img/budaya-marawis.svg', 1, 80),
(106, 'Kuliner pesisir: pecak bandeng dan laksa (ilustrasi)', 'Kuliner', 'Setiap hari di warung warga', 'Pecak bandeng dengan sambal kencur, ikan bakar hasil tangkapan pagi, dan laksa khas Tangerang mudah ditemui di warung dekat pantai dan pasar mingguan. Rasakan juga rengginang rebon dan kerupuk ikan buatan warga.', '/assets/img/budaya-kuliner.svg', 1, 90);
