INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (201, 'Musim angin barat: nelayan diminta cek gelombang sebelum melaut (ilustrasi)', '2026-11-20', 'Perikanan', 'Memasuki akhir November, angin barat mulai bertiup di perairan utara Tangerang. Pemerintah desa bersama kelompok nelayan mengingatkan seluruh nelayan Marga Mulya untuk memeriksa tinggi gelombang setiap pagi sebelum berangkat melaut.\n\nPatokan yang dipakai kelompok nelayan: gelombang di bawah 1,25 meter masih aman untuk perahu kecil, 1,25 sampai 2,5 meter berbahaya untuk perahu motor tempel, dan di atas 2,5 meter semua perahu kecil sebaiknya tidak melaut. Prakiraan gelombang bisa dilihat di halaman Cuaca darat dan laut di website desa, yang diambil dari data prakiraan laut terbuka.\n\nKetua kelompok nelayan juga meminta setiap perahu membawa pelampung untuk semua awak, lampu, dan HP yang terisi penuh di dalam kantong plastik kedap air. Kabarkan rencana pulang kepada keluarga atau rekan di dermaga.\n\nNelayan yang belum memiliki Kartu KUSUKA diimbau segera mendaftar, karena kartu ini menjadi syarat untuk menerima bantuan alat keselamatan dan asuransi nelayan. Pendampingan pendaftaran tersedia di kantor desa setiap hari kerja.\n\nDalam keadaan darurat di laut, hubungi 112 atau Basarnas 115. Nomor ini juga tersimpan di halaman Kontak dan tetap bisa dibuka tanpa sinyal setelah website dipasang di HP.', NULL);
INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (202, 'Kelompok Tani Jamblang siapkan musim tanam padi rendeng (ilustrasi)', '2026-11-17', 'Pertanian', 'Kelompok Tani Jamblang mulai menyiapkan musim tanam padi rendeng yang bertepatan dengan datangnya musim hujan. Persemaian dimulai serentak supaya jadwal pengairan dan panen bisa diatur bersama.\n\nSekitar 330 hektare sawah di Marga Mulya diairi lewat saluran irigasi dan sebagian mengandalkan air hujan. Petani diminta membersihkan saluran tersier di depan sawahnya masing-masing sebelum air dialirkan, supaya tidak meluap ke jalan dan permukiman.\n\nPada 2023, sawah Marga Mulya pernah menjadi lokasi percontohan benih padi Cakrabuana. Pengalaman itu kembali dibagikan dalam pertemuan kelompok, termasuk cara memilih benih dan mengatur jarak tanam.\n\nPetani yang belum masuk rencana kebutuhan kelompok (RDKK) untuk pupuk bersubsidi diminta segera melapor ke ketua kelompok. Prakiraan hujan dan saran waktu menyemprot atau menjemur gabah bisa dilihat di halaman Cuaca darat dan laut.', NULL);
INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (203, 'Posyandu Kampung KB Bebulak: jadwal dan yang perlu dibawa (ilustrasi)', '2026-11-14', 'Kesehatan', 'Posyandu di Kampung KB Bebulak, RW 03, buka sebulan sekali untuk balita, ibu hamil, dan lansia. Layanannya meliputi penimbangan, pengukuran tinggi badan, imunisasi, pemberian vitamin A, dan penyuluhan gizi.\n\nOrang tua diminta membawa buku KIA (buku pink) dan datang pagi supaya antrean tidak menumpuk. Balita yang berat badannya tidak naik dua bulan berturut-turut akan dirujuk ke bidan desa untuk pemeriksaan lebih lanjut.\n\nKader posyandu juga mendata ibu hamil dan keluarga yang belum memiliki jamban sehat sebagai bagian dari upaya pencegahan stunting. Data ini dipakai desa untuk menentukan sasaran bantuan pembangunan jamban.\n\nJadwal posyandu terdekat bisa dilihat di halaman Agenda dan bisa langsung disimpan ke kalender HP lengkap dengan pengingat sehari sebelumnya.', NULL);
INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (204, 'APBDes dibuka: ke mana saja dana desa dibelanjakan (ilustrasi)', '2026-11-10', 'Pemerintahan', 'Pemerintah desa membuka rincian Anggaran Pendapatan dan Belanja Desa (APBDes) di website desa. Warga bisa melihat sumber pendapatan desa, pos belanja, dan berapa persen yang sudah terealisasi.\n\nBelanja terbesar tahun ini dipakai untuk pembangunan jalan lingkungan, perbaikan tambatan perahu, dan normalisasi saluran air. Sebagian lain dipakai untuk posyandu, pelatihan usaha, dan Bantuan Langsung Tunai Dana Desa.\n\nSetiap proyek pembangunan dilengkapi lokasi, besar anggaran, sumber dana, progres, serta foto sebelum dan sesudah. Warga yang menemukan pekerjaan tidak sesuai bisa melapor lewat Aspirasi warga, boleh tanpa nama.\n\nKeterbukaan ini sejalan dengan kewajiban desa menyampaikan informasi publik. Warga juga bisa meminta salinan dokumen anggaran lewat aspirasi dengan kategori Permohonan informasi publik.', NULL);
INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (205, 'Pemuda dan pengunjung tanam bibit mangrove di pesisir utara (ilustrasi)', '2026-11-03', 'Lingkungan', 'Karang Taruna Marga Mulya bersama pengunjung dari sekolah dan kampus menanam bibit bakau di pesisir utara desa. Penanaman dipusatkan di titik yang paling sering tergerus ombak dan terkena rob.\n\nAkar mangrove menahan lumpur dan meredam ombak, sehingga garis pantai tidak terus mundur. Hutan mangrove juga menjadi tempat ikan, udang, dan kepiting berkembang biak, yang pada akhirnya menambah tangkapan nelayan.\n\nBibit yang ditanam diberi tanda dan dipantau setiap bulan. Bibit yang mati diganti pada kegiatan berikutnya. Warga dan pengunjung yang ingin ikut bisa mendaftar sebagai relawan lewat halaman Agenda.\n\nPengunjung diingatkan untuk tidak menginjak atau mencabut bibit mangrove saat berwisata, sesuai kode etik pengunjung desa.', NULL);
INSERT IGNORE INTO berita (id, judul, tanggal, kategori, isi, foto) VALUES (206, 'Marawis dan gambang kromong meriahkan Muludan kampung (ilustrasi)', '2026-10-25', 'Budaya', 'Peringatan Maulid Nabi di Marga Mulya berlangsung meriah dengan penampilan marawis remaja masjid dan gambang kromong dari sanggar kampung. Warga dari lima RW berkumpul di balai desa sejak sore.\n\nArak-arakan panjang mulud berisi telur hias dan makanan dibawa keliling kampung, lalu dibagikan kepada warga dan anak-anak. Tradisi ini menjadi ajang silaturahmi antarwarga pesisir dan warga di sekitar sawah.\n\nPemerintah desa mendata kelompok seni yang masih aktif supaya bisa dilibatkan dalam penyambutan tamu dan kunjungan rombongan. Kelompok seni yang belum terdata bisa menghubungi kantor desa.\n\nInformasi budaya dan kesenian Marga Mulya kini bisa dibaca di halaman Wisata dan Budaya.', NULL);
INSERT IGNORE INTO kredit_foto (id, judul, pembuat, sumber_url, lisensi, lisensi_url, keterangan, urutan) VALUES
(6, 'Ilustrasi panorama desa, kepala desa, dan budaya', 'Tim EcoQuest Marga Mulya', '', 'Karya sendiri', '', 'Gambar vektor di beranda, sambutan, footer, dan halaman budaya. Bukan foto asli.', 2),
(7, 'Prakiraan gelombang laut', 'Open-Meteo Marine', 'https://open-meteo.com/en/docs/marine-weather-api', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'Dipakai di halaman Cuaca darat dan laut.', 6);
INSERT IGNORE INTO asisten_menu (id, induk_id, judul, pertanyaan, jawaban, tautan, label_tautan, urutan, aktif) VALUES
(1, 0, 'Surat dan administrasi', 'Apa yang ingin Anda urus?', '', '', '', 1, 1),
(2, 0, 'Bantuan sosial dan program pemerintah', 'Pilih yang ingin Anda ketahui:', '', '', '', 2, 1),
(3, 0, 'Wisata, budaya, dan kunjungan', 'Pilih informasi untuk pengunjung:', '', '', '', 3, 1),
(4, 0, 'Produk UMKM warga', 'Mau membeli atau menitipkan produk?', '', '', '', 4, 1),
(5, 0, 'Aspirasi, pertanyaan, dan pengaduan', 'Pilih yang Anda perlukan:', '', '', '', 5, 1),
(6, 0, 'Darurat dan cuaca', 'Pilih informasi keselamatan:', '', '', '', 6, 1),
(7, 0, 'Info desa dan kantor desa', 'Pilih informasi desa:', '', '', '', 7, 1),
(11, 1, 'Cara mengajukan surat, langkah demi langkah', '', '1. Pilih jenis surat di halaman Layanan, lalu centang dokumen yang sudah siap.\n2. Isi form Ajukan surat online: nama, WhatsApp, dan keperluan. Tidak perlu mengunggah KTP atau KK.\n3. Simpan kode pengajuan yang diawali SRT-.\n4. Petugas memeriksa dan menyiapkan surat, biasanya 1 hari kerja. Kabar dikirim lewat WhatsApp atau email.\n5. Saat status Siap diambil, datang ke kantor desa membawa dokumen asli, ambil nomor antrean lewat QR, lalu tanda tangan dan ambil surat.', '/data-desa?grup=Layanan+surat#alur', 'Lihat alur pengajuan', 1, 1),
(12, 1, 'Syarat surat yang sering dicari', 'Surat apa yang Anda perlukan?', '', '', '', 2, 1),
(13, 1, 'Izin kunjungan rombongan, KKN, atau penelitian', '', 'Rombongan 10 orang atau lebih, mahasiswa KKN, dan peneliti mengajukan izin lewat layanan surat paling lambat 7 hari sebelum kegiatan.\nSiapkan surat permohonan dari sekolah, kampus, atau instansi, daftar anggota, rencana kegiatan, dan nama penanggung jawab.\nPetugas akan mengabari lewat WhatsApp dan membantu menyiapkan pemandu serta jadwal.', '/data-desa?grup=Layanan+surat&izin=1#surat', 'Ajukan izin kunjungan', 3, 1),
(14, 1, 'Cek status surat saya', '', 'Masukkan kode pengajuan yang diawali SRT- di kotak Lacak pengajuan surat. Tahapannya: Diterima, Diproses, Siap diambil, Selesai.', '/data-desa?grup=Layanan+surat#surat', 'Lacak surat', 4, 1),
(15, 1, 'Antrean di kantor desa', '', 'Di meja layanan kantor desa ada QR antrean. Pindai dengan kamera HP untuk mengambil nomor, lalu duduk menunggu. Halaman antrean memberi tahu berapa orang lagi sebelum giliran Anda.', '/data-desa?grup=Layanan+surat#antrean', 'Lihat antrean hari ini', 5, 1),
(16, 1, 'Biaya, lama proses, dan jam layanan', '', 'Semua surat keterangan di kantor desa gratis.\nKebanyakan selesai dalam 1 hari kerja. Surat yang diteruskan ke Disdukcapil (KK, pindah, akta) butuh waktu tambahan di sana.\nJam layanan: {jam_layanan}.', '', '', 6, 1),
(121, 12, 'Surat keterangan tidak mampu (SKTM)', '', 'Bawa KTP, Kartu Keluarga, dan surat pengantar RT dan RW. Sebutkan keperluannya, misalnya keringanan biaya sekolah atau berobat.\nGratis, selesai 1 hari kerja.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 1, 1),
(122, 12, 'Surat keterangan domisili', '', 'Bawa KTP, Kartu Keluarga, dan surat pengantar RT. Untuk pendatang, sertakan bukti tinggal seperti surat kontrak rumah.\nGratis, selesai 1 hari kerja.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 2, 1),
(123, 12, 'Surat keterangan usaha', '', 'Cocok untuk nelayan, pedagang, atau pengrajin yang butuh syarat pinjaman atau bantuan usaha. Bawa KTP, KK, pengantar RT, dan foto tempat usaha bila ada.\nGratis, 1 sampai 2 hari kerja.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 3, 1),
(124, 12, 'Surat pengantar nikah', '', 'Bawa KTP dan KK calon pengantin, akta kelahiran, pas foto 3x4 dan 4x6 latar biru, serta pengantar RT dan RW. Setelah surat desa selesai, lanjutkan pendaftaran ke KUA Kecamatan Mauk.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 4, 1),
(125, 12, 'Surat keterangan kelahiran', '', 'Bawa surat keterangan lahir dari bidan atau rumah sakit, KK dan KTP kedua orang tua, buku nikah, dan KTP dua saksi. Surat ini dipakai mengurus akta kelahiran di Disdukcapil.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 5, 1),
(126, 12, 'Surat keterangan kematian', '', 'Bawa pengantar RT dan RW, KK dan KTP almarhum atau almarhumah, serta KTP pelapor. Surat ini dipakai untuk akta kematian dan pembaruan KK.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 6, 1),
(127, 12, 'Pengantar SKCK, KK, atau pindah domisili', '', 'SKCK: KTP, KK, pas foto, pengantar RT.\nPerubahan KK atau pindah: KK dan KTP asli, pengantar RT dan RW, alamat tujuan. Dokumen akhirnya diterbitkan Disdukcapil Kabupaten Tangerang.', '/data-desa?grup=Layanan+surat#surat', 'Ajukan surat ini', 7, 1),
(21, 2, 'Cek apakah saya penerima bantuan', '', 'Buka Pantau bansos, lalu ketik nama lengkap sesuai KTP dan nomor RT. Nama penerima selalu disamarkan dan tidak perlu NIK.\nUntuk bantuan dari Kementerian Sosial seperti PKH dan Sembako, cek juga di cekbansos.kemensos.go.id.', '/data-desa?grup=Pantau+bansos#cek-bansos', 'Cek status penerima', 1, 1),
(22, 2, 'Daftar program bantuan dan syaratnya', 'Program mana yang ingin Anda ketahui?', '', '', '', 2, 1),
(23, 2, 'Bantuan untuk nelayan dan petani', 'Pilih program:', '', '', '', 3, 1),
(24, 2, 'Usulkan keluarga yang layak dibantu', '', 'Sampaikan usulan ke ketua RT, atau kirim aspirasi dengan kategori Bansos. Usulan dibahas dalam musyawarah desa sebelum penerima ditetapkan.', '/kontak?kategori=Bansos#aspirasi', 'Kirim usulan', 4, 1),
(25, 2, 'Laporkan bantuan salah sasaran', '', 'Laporan boleh tanpa nama. Tulis program, RT, dan alasan Anda. Anda mendapat kode ADU- untuk memantau tindak lanjutnya.', '/kontak?kategori=Bansos#aspirasi', 'Laporkan', 5, 1),
(221, 22, 'Program Keluarga Harapan (PKH)', '', 'Bantuan tunai bertahap untuk keluarga miskin yang punya ibu hamil, balita, anak sekolah, lansia, atau disabilitas berat. Syarat utamanya terdaftar di DTKS. Usulkan lewat musyawarah desa atau ketua RT.', '/data-desa?grup=Pantau+bansos', 'Lihat semua program', 1, 1),
(222, 22, 'Program Sembako (BPNT)', '', 'Bantuan bahan pangan pokok untuk keluarga miskin dan rentan yang terdaftar di DTKS. Jadwal penyaluran ditentukan Kementerian Sosial.', '/data-desa?grup=Pantau+bansos', 'Lihat semua program', 2, 1),
(223, 22, 'BLT Dana Desa', '', 'Bantuan tunai dari Dana Desa untuk keluarga miskin yang belum menerima bantuan lain. Penerima ditetapkan lewat musyawarah desa dan diumumkan di papan kantor desa.', '/data-desa?grup=Pantau+bansos', 'Lihat semua program', 3, 1),
(224, 22, 'Program Indonesia Pintar (PIP)', '', 'Bantuan biaya sekolah untuk anak dari keluarga kurang mampu. Hubungi wali kelas atau operator sekolah. Desa membantu dengan surat keterangan tidak mampu (SKTM).', '/data-desa?grup=Pantau+bansos', 'Lihat semua program', 4, 1),
(225, 22, 'Jaminan kesehatan PBI (KIS)', '', 'Iuran BPJS Kesehatan warga tidak mampu dibayar pemerintah. Ajukan lewat desa dengan membawa Kartu Keluarga, lalu desa meneruskan ke Dinas Sosial.', '/data-desa?grup=Pantau+bansos', 'Lihat semua program', 5, 1),
(231, 23, 'Kartu KUSUKA', '', 'Kartu tanda pelaku usaha perikanan dari Kementerian Kelautan dan Perikanan. Menjadi syarat bantuan alat tangkap, mesin perahu, dan asuransi nelayan. Daftar lewat ketua kelompok nelayan atau penyuluh perikanan kecamatan.', '/data-desa?grup=Pantau+bansos', 'Lihat detail program', 1, 1),
(232, 23, 'Asuransi nelayan', '', 'Santunan bila terjadi kecelakaan saat melaut. Syaratnya memiliki Kartu KUSUKA. Daftar lewat ketua kelompok nelayan.', '/data-desa?grup=Pantau+bansos', 'Lihat detail program', 2, 1),
(233, 23, 'Bantuan alat keselamatan melaut', '', 'Pelampung, jaket keselamatan, dan lampu untuk perahu kecil. Untuk nelayan yang terdaftar di kelompok nelayan dan memiliki Kartu KUSUKA.', '/data-desa?grup=Pantau+bansos', 'Lihat detail program', 3, 1),
(234, 23, 'Pupuk bersubsidi untuk petani', '', 'Daftar ke ketua Kelompok Tani supaya masuk rencana kebutuhan kelompok (RDKK), lalu tebus pupuk di kios resmi dengan KTP.', '/data-desa?grup=Pantau+bansos', 'Lihat detail program', 4, 1),
(31, 3, 'Tempat wisata, harga, dan jam buka', '', 'Ada Pantai Pasir Putih, kawasan mangrove, kampung nelayan, dan kelas kerajinan batok kelapa. Harga dan jam buka tiap tempat tertulis di halaman Wisata. Pengunjung perorangan dan keluarga cukup datang langsung.', '/wisata', 'Lihat semua wisata', 1, 1),
(32, 3, 'Budaya dan kesenian', '', 'Sedekah laut, panen bandeng bersama, marawis, gambang kromong, pencak silat dan palang pintu, serta kuliner pecak bandeng. Jadwal dan ceritanya ada di bagian Budaya dan kesenian.', '/wisata#budaya', 'Lihat budaya desa', 2, 1),
(33, 3, 'Waktu terbaik berkunjung', '', 'Pagi 06.00 sampai 10.00 atau sore menjelang senja. Musim kemarau paling cocok untuk pantai. Saat angin barat (Desember sampai Februari), cek prakiraan gelombang dan air pasang dulu.', '/cuaca', 'Lihat cuaca dan gelombang', 3, 1),
(34, 3, 'Kode etik pengunjung', '', 'Jaga mangrove dan pantai, bawa pulang sampah, minta izin sebelum memotret warga, berpakaian sopan di kampung, dan jangan berenang saat ombak tinggi.', '/wisata#kode-etik', 'Baca kode etik lengkap', 4, 1),
(35, 3, 'Datang rombongan, KKN, atau penelitian', '', 'Rombongan 10 orang atau lebih, KKN, dan penelitian mengajukan izin kunjungan lewat layanan surat paling lambat 7 hari sebelumnya, supaya pemandu dan jadwal bisa disiapkan.', '/data-desa?grup=Layanan+surat&izin=1#surat', 'Ajukan izin kunjungan', 5, 1),
(36, 3, 'Rute, parkir, dan petunjuk arah', '', 'Setiap halaman wisata punya tombol Petunjuk arah di Google Maps. Parkirlah di tempat yang disediakan dan jangan menutup jalan atau akses perahu nelayan.', '/kontak#peta', 'Buka peta desa', 6, 1),
(41, 4, 'Cara memesan produk', '', 'Pilih produk di halaman UMKM, lalu tekan Pesan lewat WhatsApp. Pesan sudah terisi otomatis dengan nama produk dan harganya. Pembayaran dan pengiriman disepakati langsung dengan penjual.', '/umkm', 'Lihat produk', 1, 1),
(42, 4, 'Cara menitipkan produk saya', 'Pilih yang ingin Anda ketahui:', '', '', '', 2, 1),
(43, 4, 'Pembayaran dan pengiriman', '', 'Website desa tidak menerima pembayaran. Bayar langsung ke penjual setelah sepakat lewat WhatsApp, sebaiknya saat barang diterima atau lewat rekening atas nama penjual. Cara kirim tiap produk (ambil sendiri, antar, atau paket) tertulis di kartunya.', '', '', 3, 1),
(421, 42, 'Syarat dan langkahnya', '', '1. Isi form Ajukan produk: nama usaha, produk, harga, satuan, dan WhatsApp.\n2. Tambahkan sampai 3 foto yang terang dan jelas.\n3. Petugas meninjau 1 sampai 2 hari kerja.\n4. Produk tampil di website, dan pesanan masuk langsung ke WhatsApp Anda. Gratis.', '/umkm#ajukan', 'Ajukan produk', 1, 1),
(422, 42, 'Tips foto produk yang menarik', '', 'Foto di dekat jendela pada siang hari, pakai alas polos, tampilkan isi dan kemasannya, dan bersihkan lensa kamera HP. Hindari memotret wajah orang lain tanpa izin.', '', '', 2, 1),
(423, 42, 'Cek status pengajuan', '', 'Masukkan kode yang diawali PRD- di kotak Cek pengajuan. Tahapannya: Diterima, Ditinjau, Diterbitkan.', '/umkm#cek-ajuan', 'Cek pengajuan', 3, 1),
(51, 5, 'Kirim aspirasi atau laporan', '', 'Tulis masalahnya, misalnya jalan rusak atau lampu mati, tambahkan lokasi dan foto bila ada. Anda mendapat kode ADU- untuk melacak perkembangannya.', '/kontak#aspirasi', 'Kirim aspirasi', 1, 1),
(52, 5, 'Bertanya kepada petugas desa', '', 'Pilih kategori Pertanyaan umum di form aspirasi. Jawaban dikirim ke WhatsApp atau email Anda, dan bisa dilacak dengan kode ADU-. Untuk pertanyaan singkat, Anda juga bisa langsung chat WhatsApp desa.', '/kontak?kategori=Pertanyaan#aspirasi', 'Tulis pertanyaan', 2, 1),
(53, 5, 'Kirim tanpa nama', '', 'Centang Kirim tanpa nama di form aspirasi. Simpan baik-baik kode ADU- karena petugas tidak bisa menghubungi Anda.', '/kontak#aspirasi', 'Kirim tanpa nama', 3, 1),
(54, 5, 'Lacak aspirasi saya', '', 'Masukkan kode ADU- di kotak Lacak aspirasi untuk melihat tahap dan tanggapan petugas.', '/kontak#aspirasi', 'Lacak aspirasi', 4, 1),
(55, 5, 'Lihat Papan Aspirasi warga', '', 'Semua aspirasi yang sudah diperiksa petugas tampil di Papan Aspirasi tanpa nama dan kontak pelapor. Anda bisa menekan Saya juga mengalami untuk mendukung laporan warga lain.', '/kontak#papan', 'Buka Papan Aspirasi', 5, 1),
(61, 6, 'Nomor darurat', '', '112 untuk semua keadaan darurat (bebas pulsa)\n119 ambulans\n110 polisi\n113 pemadam kebakaran\n115 Basarnas untuk kecelakaan di laut atau orang hilang', '/kontak#darurat', 'Buka nomor darurat', 1, 1),
(62, 6, 'Cuaca laut untuk nelayan', '', 'Patokan kelompok nelayan: gelombang di bawah 1,25 m aman untuk perahu kecil, 1,25 sampai 2,5 m berbahaya untuk perahu motor tempel, di atas 2,5 m sebaiknya tidak melaut. Prakiraan 3 hari ada di halaman Cuaca.', '/cuaca#laut', 'Lihat gelombang laut', 2, 1),
(63, 6, 'Cuaca darat untuk petani', '', 'Halaman Cuaca memberi saran harian: kapan cocok menjemur gabah, kapan sebaiknya tidak menyemprot karena angin atau hujan, dan peringatan hujan lebat.', '/cuaca#darat', 'Lihat cuaca darat', 3, 1),
(64, 6, 'Siaga banjir dan rob', '', 'Saat hujan lebat atau bulan purnama, air pasang bisa masuk ke pesisir. Hindari pantai, tambak, dan saluran sawah. Peta zona rawan ada di halaman Profil.', '/profil#peta-desa', 'Lihat zona rawan', 4, 1),
(71, 7, 'Jam layanan dan alamat kantor desa', '', 'Kantor desa buka {jam_layanan}.\nAlamat: {alamat}\nWhatsApp: +{wa}', '/kontak', 'Buka halaman Kontak', 1, 1),
(72, 7, 'Data penduduk dan potensi desa', '', 'Jumlah penduduk, pekerjaan, pendidikan, kesehatan, agama, perikanan, pertanian, dan ekonomi desa tersedia lengkap dan bisa diunduh dalam bentuk CSV.', '/data-desa', 'Lihat data desa', 2, 1),
(73, 7, 'Anggaran (APBDes) dan pembangunan', '', 'Pendapatan, belanja, dan realisasi anggaran desa dibuka untuk umum, begitu juga progres setiap proyek pembangunan.', '/data-desa?grup=Transparansi', 'Lihat APBDes', 3, 1),
(74, 7, 'Agenda desa dan jadi relawan', '', 'Lihat kegiatan desa, simpan ke kalender HP, dan daftar jadi relawan tanam mangrove atau bersih pantai.', '/agenda', 'Lihat agenda', 4, 1),
(75, 7, 'Pasang website di HP (bisa tanpa sinyal)', '', 'Android: buka menu Chrome, pilih Tambahkan ke layar utama atau Instal aplikasi.\niPhone: buka di Safari, tekan tombol Bagikan, lalu pilih Tambah ke Layar Utama.\nHalaman yang pernah dibuka, termasuk nomor darurat, tetap bisa dibuka saat sinyal hilang.', '', '', 5, 1),
(76, 7, 'Privasi dan data pribadi saya', '', 'Website ini tidak pernah meminta KTP, KK, atau NIK. Nama dan kontak dihapus otomatis setelah urusan selesai. Untuk meminta salinan, perbaikan, atau penghapusan data, hubungi petugas lewat WhatsApp atau email desa.', '/kontak#privasi', 'Baca kebijakan privasi', 6, 1);
